<?php require_once "../db.php";require_role("Admin");$r=$conn->query("SELECT q.*,t.name teacher_name FROM quiz q LEFT JOIN teacher t ON t.id=q.created_by ORDER BY q.id DESC");?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quizzes</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/admin_sidebar.php";?></div><main class="col-lg-10"><div class="py-4"><h2>Manage Quizzes</h2><div class="card panel-card"><div class="card-body table-responsive"><table class="table"><thead><tr><th>Title</th><th>Subject</th><th>Teacher</th><th>Duration</th><th>Questions</th></tr></thead><tbody><?php while($q=$r->fetch_assoc()):?><tr><td><?=e($q["title"])?></td><td><?=e($q["subject"])?></td><td><?=e($q["teacher_name"]??"")?></td><td><?=$q["duration"]?> min</td><td><?=$q["total_questions"]?></td></tr><?php endwhile;?></tbody></table></div></div></div></main></div></div></body></html>
